-- LLD interview practice: problems (with hidden rubrics), attempts, and AI usage counters.
CREATE TABLE IF NOT EXISTS problems (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  difficulty TEXT NOT NULL DEFAULT 'Medium',
  summary TEXT NOT NULL DEFAULT '',
  statement TEXT NOT NULL DEFAULT '',
  rubric TEXT NOT NULL DEFAULT '{}',      -- JSON: checklist per step, never sent to learners
  published INTEGER NOT NULL DEFAULT 1,
  position INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  problem_id INTEGER NOT NULL REFERENCES problems(id) ON DELETE CASCADE,
  data TEXT NOT NULL DEFAULT '{}',        -- JSON: answers, reviews, twist question, report
  step INTEGER NOT NULL DEFAULT 1,
  status TEXT NOT NULL DEFAULT 'active',  -- active | done
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_attempts_user ON attempts(user_id, updated_at);
CREATE TABLE IF NOT EXISTS ai_usage (
  user_id INTEGER NOT NULL,
  day TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, day)
);

INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('parking-lot', 'Parking Lot', 'Easy', 'Multi-floor parking with different spot sizes, tickets and fees.', 'Design a parking lot system for a multi-floor building.

Vehicles of different sizes (bike, car, truck) arrive and need a spot that fits them. The system issues a ticket on entry and calculates the fee on exit. The interviewer has kept the details deliberately vague: ask clarifying questions and decide the scope yourself.', '{"requirements": ["Asks about vehicle types and spot sizes and which vehicle fits which spot", "Multiple floors and entry/exit gates", "Ticket issued on entry; fee calculated on exit", "Pricing model (hourly, flat, by vehicle type)", "Payment method(s) at exit", "What happens when the lot is full", "Non-functional: concurrent entries at multiple gates must not double-assign a spot", "Explicitly keeps out of scope things like reservations or valet unless asked"], "entities": ["ParkingLot (singleton or single instance), Floor, ParkingSpot with type/size", "Vehicle hierarchy or Vehicle with VehicleType", "Ticket (entry time, spot, vehicle)", "EntryGate / ExitGate or a ParkingService", "Payment / FeeCalculator / PricingStrategy", "Relationships: Lot has Floors, Floor has Spots (composition); Ticket references Spot and Vehicle (association)"], "uml": ["Class diagram consistent with the entities step", "Spot allocation separated from gates (e.g. SpotAllocationStrategy)", "Pricing as a Strategy so new fee rules don''t change core classes", "Correct relationship notation (composition for floors/spots, association for ticket)", "Patterns named with a reason: Strategy for pricing/allocation, Singleton or Factory where justified"], "code": ["parkVehicle(vehicle) finds a fitting free spot, marks it occupied, returns a Ticket", "unpark(ticket) frees the spot and computes the fee via the pricing strategy", "Handles lot full / no fitting spot cleanly", "Thread safety around spot assignment (synchronized/locks/atomic)", "Code matches the UML; no god class; SOLID respected"], "twist": ["Add EV charging spots that charge per kWh as well as per hour", "Two cars at different gates try to take the last spot at the same moment", "Introduce monthly passes / reserved spots for subscribers", "Weekend pricing that differs from weekday pricing"]}', 1, 0, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('elevator', 'Elevator System', 'Medium', 'Multiple elevators serving floors, with request scheduling.', 'Design the control system for a building with multiple elevators.

People call an elevator from a floor (up/down buttons) and choose a destination floor from inside the cabin. The system decides which elevator serves which request. Clarify the details before designing.', '{"requirements": ["Number of elevators and floors; capacity/weight limit", "External requests (floor + direction) vs internal requests (destination floor)", "Elevator states: moving up, moving down, idle; doors open/closed", "Scheduling goal (minimise wait time, nearest elevator, SCAN/LOOK)", "Emergency stop / maintenance mode", "Non-functional: requests arrive concurrently; system must be responsive"], "entities": ["ElevatorSystem / ElevatorController", "Elevator (current floor, direction, state, request queue)", "Request (floor, direction, type internal/external)", "Floor with buttons; Display", "Scheduler / DispatchStrategy", "Direction and ElevatorState enums"], "uml": ["Controller depends on a dispatch Strategy interface (pluggable algorithms)", "State pattern (or explicit state machine) for elevator states", "Observer for displays/floors notified of elevator position, if justified", "Diagram consistent with entities; correct multiplicities (system has many elevators)"], "code": ["requestElevator(floor, direction) picks an elevator via the strategy", "Elevator processes requests in a sensible order (e.g. LOOK/SCAN), not FIFO zig-zag", "Clear state transitions; no invalid moves", "Concurrency: request queues are thread-safe", "Code mirrors UML; responsibilities split sensibly"], "twist": ["Add a VIP/fire-service mode that overrides all requests", "Make one elevator express-only between ground and floors 20+", "Two requests arrive for the same floor in opposite directions at once", "Swap the scheduling algorithm at runtime during peak hours"]}', 1, 1, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('bookmyshow', 'BookMyShow (Movie Ticket Booking)', 'Hard', 'Cities, theatres, shows and seat booking without double-booking.', 'Design a movie ticket booking system like BookMyShow.

Users pick a city, a movie, a theatre and a show, choose seats on a seat map and pay to confirm the booking. Many users book the same popular show at the same time. Scope it with the interviewer before you design.', '{"requirements": ["Browse by city, movie, theatre, show time", "Seat map with seat types/prices (regular, premium)", "Select seats, temporarily hold them, then pay to confirm", "Hold expiry if payment isn''t completed", "Cancellation/refund policy (in or out of scope)", "Non-functional: no double booking of a seat under heavy concurrency", "Notifications/booking confirmation"], "entities": ["City, Theatre, Screen, Seat (type), Movie, Show (movie + screen + time)", "ShowSeat / seat status per show (available, held, booked)", "Booking (user, show, seats, status, amount)", "Payment, User", "BookingService / SeatLockProvider", "Relationships: Theatre has Screens has Seats; Show links Movie and Screen"], "uml": ["Seat status per show separated from physical Seat", "Seat locking behind an interface (in-memory vs distributed)", "Pricing strategy per seat type/show", "Observer/notification for booking confirmation if justified", "Diagram consistent with entities; correct cardinalities"], "code": ["holdSeats(show, seats, user) atomically checks and locks all requested seats or none", "confirmBooking(hold, payment) moves held seats to booked", "Expired holds are released", "Concurrency handled explicitly (locks, compare-and-set, transactions)", "Clean separation: BookingService doesn''t do payment internals"], "twist": ["Two users click the same seat at the same millisecond", "Add a ''block 10 seats for a corporate group'' feature", "Payment succeeds but the hold already expired: what happens?", "Dynamic pricing: prices rise as the show fills up"]}', 1, 2, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('splitwise', 'Splitwise (Expense Sharing)', 'Medium', 'Groups, expenses split different ways, and simplified balances.', 'Design an expense-sharing app like Splitwise.

Users add expenses within a group and split them between members. The app shows who owes whom and can simplify debts. Clarify the split types and features with the interviewer first.', '{"requirements": ["Users and groups; expenses can also be between two users", "Split types: equal, exact amounts, percentage, shares", "Validation: splits must add up to the total", "Balance sheet: who owes whom", "Settle up / record payment", "Simplify debts (minimise number of transactions) as optional/advanced", "Non-functional: amounts in money-safe type (no floating point errors)"], "entities": ["User, Group", "Expense (paidBy, amount, splits, description)", "Split hierarchy or SplitType + Split(user, amount)", "BalanceSheet / Ledger", "ExpenseService / SplitStrategy"], "uml": ["Split calculation as Strategy (EqualSplit, ExactSplit, PercentSplit)", "Factory for creating the right split type, if justified", "Balance tracking separated from Expense", "Relationships consistent with entities"], "code": ["addExpense(paidBy, amount, users, splitType, values) validates and updates balances", "getBalances(user) returns net amounts correctly", "Rounding handled (e.g. 100 split 3 ways)", "Simplify debts algorithm if attempted is correct (greedy max creditor/debtor)", "No float money; SOLID respected"], "twist": ["Add multi-currency expenses", "Add a new split type: by item (each person pays for what they ordered)", "Someone edits an old expense: how do balances update?", "Simplify debts across the whole group"]}', 1, 3, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('rate-limiter', 'Rate Limiter', 'Medium', 'Limit requests per user/API using pluggable algorithms.', 'Design a rate limiter that an API server calls before handling each request.

It decides whether a request from a client should be allowed or rejected based on configured limits. Discuss the rules and algorithms with the interviewer before designing.', '{"requirements": ["Limit by what key: user, IP, API key, endpoint", "Limit rules: N requests per time window, different per tier/endpoint", "Algorithms: fixed window, sliding window log/counter, token bucket, leaky bucket", "Behaviour on reject (429, retry-after)", "Non-functional: very low latency, thread safe, memory bounded", "Single node vs distributed (likely out of scope or follow-up)"], "entities": ["RateLimiter interface", "Concrete limiters: TokenBucket, SlidingWindow, FixedWindow", "Rule / LimitConfig (key type, limit, window)", "RateLimiterService / Factory choosing limiter per rule", "Clock abstraction for testability"], "uml": ["Strategy: RateLimiter interface with interchangeable algorithms", "Factory or registry mapping rules to limiters", "Per-key state storage separated from algorithm", "Clock injected (dependency inversion)"], "code": ["allowRequest(key) correct for the chosen algorithm (e.g. token refill math)", "Thread safe per key (locks/atomics/ConcurrentHashMap)", "Memory: old keys/timestamps cleaned up", "Edge cases: burst at window boundary handled or acknowledged", "Code matches UML"], "twist": ["Make it work across 5 API servers sharing limits", "Premium users get 10x the limit, configurable at runtime", "Fixed window lets 2x the limit through at the boundary: fix it", "Add a global limit on top of per-user limits"]}', 1, 4, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('lru-cache', 'LRU Cache', 'Easy', 'Fixed-capacity cache with O(1) get/put and eviction.', 'Design an in-memory cache with a fixed capacity that evicts the least recently used entry when full.

get(key) and put(key, value) should be fast. Clarify expectations around complexity, concurrency and extensibility with the interviewer.', '{"requirements": ["Fixed capacity; evict least recently used on put when full", "get and put in O(1)", "What counts as ''use'' (get and put both)", "Generic key/value types", "Non-functional: thread safety required or not", "Extensibility: other eviction policies (LFU, FIFO) or TTL as follow-ups"], "entities": ["Cache interface (get, put)", "LRUCache implementation", "Node (key, value, prev, next)", "DoublyLinkedList", "HashMap key -> Node", "EvictionPolicy abstraction, if going for extensibility"], "uml": ["Cache interface with eviction policy as a Strategy (LRU, LFU)", "Storage (map) separated from eviction ordering", "Generic types shown", "Consistent with entities"], "code": ["HashMap + doubly linked list for O(1) operations", "get moves node to front; put updates or inserts and evicts tail when full", "Edge cases: capacity 0/1, updating existing key", "Thread safety if claimed (locks; or note ConcurrentHashMap alone isn''t enough)", "Clean, generic code"], "twist": ["Add TTL so entries also expire after N seconds", "Switch to LFU without rewriting callers", "Make it safe for 100 threads calling get/put", "Add hit/miss statistics"]}', 1, 5, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('vending-machine', 'Vending Machine', 'Easy', 'Select a product, pay, get change — a classic state machine.', 'Design a vending machine.

A user selects a product, inserts coins or notes, and receives the product and any change. An operator restocks products and collects cash. Ask the interviewer about payment and edge cases before designing.', '{"requirements": ["Products with price and stock in slots", "Accepted payment: coins/notes (denominations), maybe card", "Flow: select product, insert money, dispense, return change", "Cancel and refund", "Out of stock and insufficient change handling", "Operator: restock, collect cash"], "entities": ["VendingMachine", "Product, Slot/Inventory", "Coin/Note enum with values", "State interface with Idle, HasMoney, Dispensing (or similar)", "PaymentProcessor / ChangeCalculator"], "uml": ["State pattern for machine states", "Inventory separated from state logic", "Change calculation isolated", "Consistent with entities and correct relationships"], "code": ["Operations behave correctly per state (e.g. can''t dispense before payment)", "Change returned correctly using available denominations", "Refund on cancel", "Out-of-stock / exact-change-only handled", "State transitions clean; no giant switch on strings"], "twist": ["Add UPI/card payments alongside cash", "Machine can''t make change: what happens?", "Add a combo offer (chips + drink at a discount)", "Two products dispensed in one transaction"]}', 1, 6, strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, updated_at) VALUES ('tic-tac-toe', 'Tic-Tac-Toe', 'Easy', 'Two-player game on an N×N board with win detection.', 'Design a Tic-Tac-Toe game that two players can play.

Players take turns placing their symbol on the board; the game detects a win or a draw. Clarify board size and extensibility with the interviewer before designing.', '{"requirements": ["Board size: 3x3 or N x N", "Two players, alternating turns; symbols X/O", "Win: full row, column or diagonal; draw when board full", "Invalid moves rejected (occupied cell, out of bounds, wrong turn)", "Extensibility: more players, bot player, undo"], "entities": ["Game", "Board, Cell", "Player (human/bot), Symbol/Piece", "Move", "GameStatus enum", "WinningStrategy / rules"], "uml": ["Win-checking as a Strategy (pluggable rules)", "Player as interface (HumanPlayer, BotPlayer)", "Board separated from game flow", "Consistent with entities"], "code": ["makeMove validates and updates the board", "Win detection O(1) per move using row/col/diagonal counters, or O(N) acknowledged", "Draw detection", "Turn handling correct", "Clean separation of Game, Board and Player"], "twist": ["Support a 3-player game on a 5x5 board", "Add an undo move feature", "Add a computer player with a simple strategy", "Win condition changes to K-in-a-row on an N x N board"]}', 1, 7, strftime('%s','now'));
